SELECT Имена_станций.NAME AS Name1, Станции2004.YEAR, Станции2004.NUST, Станции2004.E, Станции2004.B, [Станции2004]![DON]/IIf([Натура99]![DON]>0,[Натура99]![DON],0.699) AS don, [Станции2004]![podm]/IIf([Натура99]![podm]>0,[Натура99]![podm],0.274) AS podm, IIf([int]>0,[int],0)+IIf([vork]>0,[vork],0) AS pech, [Доп_угли2004]![vork]/IIf([Натура99]![vork]>0,[Натура99]![vork],0.677) AS Vork, [Доп_угли2004]![int]/IIf([Натура99]![int]>0,[Натура99]![int],0.532) AS [int], [Станции2004]![kuzn]/IIf([Натура99]![kuzn]>0,[Натура99]![kuzn],0.752) AS kuzn, IIf([sver]>0,[sver],0)+IIf([chel]>0,[chel],0)+IIf([kizel]>0,[kizel],0) AS Ural, [Доп_угли2004]![sver]/IIf([Натура99]![sver]>0,[Натура99]![sver],0.316) AS sver, [Доп_угли2004]![chel]/IIf([Натура99]![chel]>0,[Натура99]![chel],0.422) AS chel, [Доп_угли2004]![kizel]/IIf([Натура99]![kizel]>0,[Натура99]![kizel],0.624) AS kizel, [Станции2004]![bashk]/IIf([Натура99]![bashk]>0,[Натура99]![bashk],0.29) AS bashk, [Станции2004]![ekib]/IIf([Натура99]![ekib]>0,[Натура99]![ekib],0.551) AS ekib, [Станции2004]![karag]/IIf([Натура99]![karag]>0,[Натура99]![karag],0.502) AS karag, IIf([nazar]>0,[nazar],0)+IIf([ibor]>0,[ibor],0)+IIf([berez]>0,[berez],0)+IIf([per]>0,[per],0) AS kan, [Доп_угли2004]![nazar]/IIf([Натура99]![nazar]>0,[Натура99]![nazar],0.484) AS nazar, [Доп_угли2004]![ibor]/IIf([Натура99]![ibor]>0,[Натура99]![ibor],0.537) AS ibor, [Доп_угли2004]![berez]/IIf([Натура99]![berez]>0,[Натура99]![berez],0.519) AS berez, [Доп_угли2004]![per]/IIf([Натура99]![per]>0,[Натура99]![per],0.537) AS per, IIf([azey]>0,[azey],0)+IIf([cher]>0,[cher],0)+IIf([jer]>0,[jer],0) AS irkut, [Доп_угли2004]![azey]/IIf([Натура99]![azey]>0,[Натура99]![azey],0.554) AS azey, [Доп_угли2004]![cher]/IIf([Натура99]![cher]>0,[Натура99]![cher],0.613) AS cher, [Доп_угли2004]![jer]/IIf([Натура99]![jer]>0,[Натура99]![jer],0.7) AS jer, [Станции2004]![hak]/IIf([Натура99]![hak]>0,[Натура99]![hak],0.656) AS hak, [Станции2004]![tuv]/IIf([Натура99]![tuv]>0,[Натура99]![tuv],0.781) AS tuv, IIf([gusin]>0,[gusin],0)+IIf([tugn]>0,[tugn],0) AS bur, [Доп_угли2004]![gusin]/IIf([Натура99]![gusin]>0,[Натура99]![gusin],0.528) AS gusin, [Доп_угли2004]![tugn]/IIf([Натура99]![tugn]>0,[Натура99]![tugn],0.708) AS tugn, IIf([har]>0,[har],0)+IIf([urt]>0,[urt],0) AS Chit, [Доп_угли2004]![har]/IIf([Натура99]![har]>0,[Натура99]![har],0.43) AS har, [Доп_угли2004]![urt]/IIf([Натура99]![urt]>0,[Натура99]![urt],0.62) AS urt, [Станции2004]![ner]/IIf([Натура99]![NER]>0,[Натура99]![NER],0.876) AS ner, [Станции2004]![raich]/IIf([Натура99]![raich]>0,[Натура99]![raich],0.38) AS raich, [Станции2004]![urg]/IIf([Натура99]![urg]>0,[Натура99]![urg],0.645) AS urg, [Станции2004]![prim]/IIf([Натура99]![prim]>0,[Натура99]![prim],0.388) AS prim, [Станции2004]![luch]/IIf([Натура99]![luch]>0,[Натура99]![luch],0.256) AS luch, [Станции2004]![mag]/IIf([Натура99]![mag]>0,[Натура99]![mag],0.64) AS mag, [Станции2004]![sah]/IIf([Натура99]![sah]>0,[Натура99]![sah],0.596) AS sah, [Станции2004]![ushum]/IIf([Натура99]![ushum]>0,[Натура99]![ushum],0.325) AS ushum, Станции2004.NUMB1120, Имена_станций.ordnumb AS numb1, Станции2004.DEP, Станции2004.OES, Станции2004.ER, Имена_областей.NAME AS oblname, Станции2004.VED, Имена_станций.Ведомство AS вед, Станции2004.OBL, Имена_станций.D, Имена_станций.R, Имена_ОЭС.name AS oesname, Имена_станций.MAIN, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group]
FROM ((((Станции2004 LEFT JOIN Натура99 ON (Станции2004.YEAR = Натура99.YEAR) AND (Станции2004.NUMB1120 = Натура99.NUMB1120)) LEFT JOIN Доп_угли2004 ON (Станции2004.NUMB1120 = Доп_угли2004.NUMB1120) AND (Станции2004.YEAR = Доп_угли2004.YEAR)) INNER JOIN Имена_станций ON Станции2004.NUMB1120 = Имена_станций.NUMB) INNER JOIN Имена_областей ON Станции2004.OBL = Имена_областей.OBL) INNER JOIN Имена_ОЭС ON Станции2004.OES = Имена_ОЭС.oes
WHERE (((Станции2004.YEAR)=2004) AND ((Станции2004.UGOL)>0));
